/**
 * Convenience helper to lookup an image asset by id
 */
export function getImageAsset(id: string): ImageAssetItem | undefined {
  return imageCatalog.find((img) => img.id === id);
}

/**
 * Convenience helper to lookup all images matching a flavour
 */
export function getImagesByFlavour(flavourName: string): ImageAssetItem[] {
  return imageCatalog.filter((img) => img.flavour.toLowerCase().includes(flavourName.toLowerCase()));
}
